package org.transittr;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.util.*;
/** Shared stop+line favourites editor, also used by launcher widget configuration. */
public final class WidgetSetupActivity extends Activity {
 private ThemeColors palette;private LinearLayout rows;private Spinner city;private EditText stop,line,label;private TextView state;private int widgetId=AppWidgetManager.INVALID_APPWIDGET_ID;private Typeface font;private final int[] cities={0,1,2,6};
 private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(font!=null)t.setTypeface(font);return t;}
 private GradientDrawable background(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(6));return d;}
 private Button button(String value,final Runnable action){Button b=new Button(this);b.setText(value);b.setTextSize(13);if(font!=null)b.setTypeface(font);b.setTextColor(palette.surface);b.setBackgroundDrawable(background(palette.ink));b.setPadding(dp(12),0,dp(12),0);b.setOnClickListener(new View.OnClickListener(){public void onClick(View view){action.run();}});return b;}
 private EditText input(LinearLayout group,String caption,boolean numeric){group.addView(text(caption,12,palette.muted));EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(14);e.setTextColor(palette.ink);if(font!=null)e.setTypeface(font);if(numeric)e.setInputType(2);e.setBackgroundDrawable(background(palette.input));e.setPadding(dp(10),0,dp(10),0);group.addView(e,new LinearLayout.LayoutParams(-1,dp(44)));return e;}
 public void onCreate(Bundle bundle){super.onCreate(bundle);requestWindowFeature(Window.FEATURE_NO_TITLE);palette=ThemeColors.of(this);palette.window(this);setResult(RESULT_CANCELED);try{font=Typeface.createFromAsset(getAssets(),"Geist-Regular.ttf");}catch(Exception ignored){}widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){boolean ours=false;for(int id:TransitWidget.ids(this))if(id==widgetId)ours=true;if(!ours){finish();return;}}
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(12),dp(20),dp(12));root.setBackgroundColor(palette.ground);setContentView(root);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(text("Kaydedilen sorgular",21,palette.ink),new LinearLayout.LayoutParams(0,-2,1));Button done=button("Bitti",new Runnable(){public void run(){complete();}});done.setTextColor(palette.ink);done.setBackgroundDrawable(background(palette.surface));top.addView(done,new LinearLayout.LayoutParams(dp(66),dp(44)));root.addView(top);TextView intro=text("Ana ekranda durağın ve hattın varışını gör.",13,palette.muted);intro.setPadding(0,dp(8),0,dp(8));root.addView(intro);
  city=new Spinner(this);city.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,new String[]{"Ankara","İstanbul","İzmir","Konya"}));root.addView(city,new LinearLayout.LayoutParams(-1,dp(44)));LinearLayout form=new LinearLayout(this);LinearLayout left=new LinearLayout(this),right=new LinearLayout(this);left.setOrientation(1);right.setOrientation(1);LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,-2,1);half.rightMargin=dp(10);form.addView(left,half);form.addView(right,new LinearLayout.LayoutParams(0,-2,1));stop=input(left,"Durak numarası",true);line=input(right,"Hat kodu",false);root.addView(form);LinearLayout names=new LinearLayout(this);names.setOrientation(1);label=input(names,"Kısa ad (isteğe bağlı)",false);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,-2);np.topMargin=dp(8);root.addView(names,np);LinearLayout.LayoutParams add=new LinearLayout.LayoutParams(-1,dp(44));add.topMargin=dp(10);root.addView(button("Durak + hattı kaydet",new Runnable(){public void run(){add();}}),add);state=text("",12,palette.muted);state.setPadding(0,dp(8),0,dp(8));root.addView(state);ScrollView scroll=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  int selected=getIntent().getIntExtra("city",getSharedPreferences("TransitActivity",0).getInt("map-city",0));for(int i=0;i<cities.length;i++)if(cities[i]==selected)city.setSelection(i);String suggestedStop=getIntent().getStringExtra("stop"),suggestedLine=getIntent().getStringExtra("line");if(suggestedStop!=null&&suggestedStop.matches("[0-9]{1,8}"))stop.setText(suggestedStop);if(suggestedLine!=null&&suggestedLine.matches("[A-Za-z0-9ÇĞİÖŞÜçğıöşü-]{0,16}"))line.setText(suggestedLine);render();
 }
 private String selectedDirection(){String value=getIntent().getStringExtra("direction");return cities[city.getSelectedItemPosition()]==getIntent().getIntExtra("city",-1)&&value!=null&&(value.equals("G")||value.equals("D"))?value:"";}
 private void add(){try{WidgetFavorites.add(this,cities[city.getSelectedItemPosition()],stop.getText().toString(),line.getText().toString(),selectedDirection(),label.getText().toString());((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(line.getWindowToken(),0);render();TransitWidget.request(this);}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
 private void render(){ArrayList<WidgetFavorites.Entry> entries=WidgetFavorites.all(this);state.setText(entries.size()+" / 12 kayıt · Boyuta göre 1–3 satır");rows.removeAllViews();if(entries.isEmpty()){TextView empty=text("Henüz kaydedilmiş sorgu yok.\nDurak numarası ve hat kodunu girip kaydet.",14,palette.muted);empty.setPadding(0,dp(14),0,0);rows.addView(empty);return;}for(final WidgetFavorites.Entry e:entries){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setBackgroundColor(palette.surface);LinearLayout description=new LinearLayout(this);description.setOrientation(1);description.setPadding(dp(12),dp(8),0,dp(8));description.addView(text(e.line+" · "+(e.label.length()>0?e.label:WidgetFavorites.cityName(e.city)),16,palette.blue));description.addView(text(e.stop+(e.direction.length()>0?" · "+e.direction:""),12,palette.muted));row.addView(description,new LinearLayout.LayoutParams(0,-2,1));description.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(TransitWidget.open(WidgetSetupActivity.this,e));}});TextView remove=text("Kaldır",12,palette.muted);remove.setGravity(Gravity.CENTER);row.addView(remove,new LinearLayout.LayoutParams(dp(62),dp(56)));remove.setOnClickListener(new View.OnClickListener(){public void onClick(View v){WidgetFavorites.remove(WidgetSetupActivity.this,e.id);render();TransitWidget.renderAll(WidgetSetupActivity.this);TransitWidget.schedule(WidgetSetupActivity.this);}});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=dp(1);rows.addView(row,rp);}}
 private void complete(){if(widgetId!=AppWidgetManager.INVALID_APPWIDGET_ID){TransitWidget.render(this,widgetId);Intent result=new Intent();result.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId);setResult(RESULT_OK,result);}TransitWidget.request(this);finish();}
}
